const upsertRunner = `-- name: UpsertRunner :exec
INSERT INTO runners (id, name, credential_hash, capabilities, fingerprint, registered_at)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (id) DO UPDATE SET
    name = excluded.name,
    credential_hash = excluded.credential_hash,
    capabilities = excluded.capabilities,
    fingerprint = excluded.fingerprint,
    wants_capabilities = 0,
    registered_at = excluded.registered_at
`

type UpsertRunnerParams struct {
	ID             string
	Name           string
	CredentialHash string
	Capabilities   string
	Fingerprint    string
	RegisteredAt   int64
}

// Registering an id that exists replaces its credential: the old one dies,
// which is how a runner that lost its credential file is recovered. The
// caller checks the token was issued for that id first.
func (q *Queries) UpsertRunner(ctx context.Context, arg UpsertRunnerParams) error {
	_, err := q.db.ExecContext(ctx, upsertRunner,
		arg.ID,
		arg.Name,
		arg.CredentialHash,
		arg.Capabilities,
		arg.Fingerprint,
		arg.RegisteredAt,
	)
	return err
}
